-- 将肃宁分公司三张默认报告图写入 report_file.content
-- 前置：已执行 V15（report_file.content、default_slot 已存在）
-- 部门：report_dept_profile.entity_code = suning 的 dept_id；若无则跳过

SET NAMES utf8mb4;
USE carbon_emissions;

SET @dept_id := (SELECT dept_id FROM report_dept_profile WHERE entity_code = 'suning' ORDER BY dept_id LIMIT 1);
SELECT IF(@dept_id IS NULL, 'WARN: 未找到 entity_code=suning 的部门，本脚本不会插入默认图', CONCAT('OK: dept_id=', @dept_id)) AS init_status;

-- cover_logo (cover_logo.png, 10016 bytes)
INSERT INTO report_file (
  dept_id, report_id, kind, role, object_key, content, original_name, mime_type,
  size_bytes, sha256, snapshot_sha256, create_by, create_time, update_by, update_time
)
SELECT @dept_id, NULL, 'default', 'cover_logo', '', UNHEX(''), 'cover_logo.png', 'image/png',
  10016, '6b57e31ab615ce4a9bcf56807d7183a999594ff5a27c276688d3a727c45e3948', '', 'system', NOW(), 'system', NOW()
FROM DUAL
WHERE @dept_id IS NOT NULL
  AND NOT EXISTS (
    SELECT 1 FROM report_file
    WHERE dept_id = @dept_id AND kind = 'default' AND role = 'cover_logo'
  );

