SELECT @dept_id, NULL, 'default', 'org_chart', '', UNHEX(''), 'org_chart.png', 'image/png',
  127292, 'dc74fab1fb56bedc7dd462b428c98ad563f237b65b7abb76e2a2c128cbe29fa7', '', 'system', NOW(), 'system', NOW()
FROM DUAL
WHERE @dept_id IS NOT NULL
