-- office_location (office_location.jpeg, 220004 bytes)
INSERT INTO report_file (
  dept_id, report_id, kind, role, object_key, content, original_name, mime_type,
  size_bytes, sha256, snapshot_sha256, create_by, create_time, update_by, update_time
)
SELECT @dept_id, NULL, 'default', 'office_location', '', UNHEX(''), 'office_location.jpeg', 'image/jpeg',
  220004, '26043204f3cbc9a22af12bb48d69cc3bd97cf98d6ed4cea2a7d788079c7da7ae', '', 'system', NOW(), 'system', NOW()
FROM DUAL
WHERE @dept_id IS NOT NULL
  AND NOT EXISTS (
    SELECT 1 FROM report_file
    WHERE dept_id = @dept_id AND kind = 'default' AND role = 'office_location'
  );

SELECT id, dept_id, kind, role, original_name, size_bytes, LENGTH(content) AS content_bytes
FROM report_file
WHERE dept_id = @dept_id AND kind = 'default' AND role IN ('cover_logo','org_chart','office_location')
ORDER BY id;
